/* tbt_fec_sclc_delta.h - generated SC-LDPC margin tables. DO NOT EDIT.
 *
 * Sources, both under review/calib:
 *   sclc-de.csv  commit b55ef67: BEC density evolution, downlink n=1..192
 *   sclc-up.csv  commit 4d072ce: 8x32 GF(16) construction scan, w=32
 *
 * Regenerate from the repository root:
 *   python3 host/gen_sclc_delta.py review/calib/sclc-de.csv \
 *       review/calib/sclc-up.csv tbtun/tbt_fec_sclc_delta.h
 * Pass --check to compare without writing; a mismatch exits 1.
 *
 * down_q16      round(delta(n) * 65536) from the density evolution.
 * up_delta_q16  max(0, m - floor(8192 / nsym)) * 65536: the
 *               conservative 256-variable core bound. Zero means
 *               the online surplus correction must add margin.
 * len_q16       round(delta(P) * 256 * 65536), where
 *               delta(P) = 0.60 * Qinv(P) / 16 and P = eps_ppm / 1e6.
 */
